function board(el){if(!el||typeof sb==="undefined")return;try{Promise.resolve(sb.rpc("get_jet_weekly",{p_weeks_ago:0})).then(r=>{const d=(r&&r.data)||[];if(!root||!el.isConnected)return;
  el.innerHTML=d.length?'<div class="jth">This week</div>'+d.slice(0,5).map(x=>'<div class="jtr'+(x.is_me?' me':'')+'"><span>'+x.rank+'. '+esc(x.display_name)+'</span><span>'+Number(x.score).toLocaleString("en-GB")+'</span></div>').join(""):""}).catch(()=>{})}catch(e){}}
