function open(){
  if(window.__pdOpen)return;
  window.__pdOpen=true;closed=false;
  if(!document.getElementById("jtCss")){const st=document.createElement("style");st.id="jtCss";st.textContent=CSS;document.head.appendChild(st)}
  root=document.createElement("div");root.id="jtRoot";root.setAttribute("role","dialog");root.setAttribute("aria-modal","true");root.setAttribute("aria-label","Seafront Jet");
  root.innerHTML='<button class="jtx" type="button">Exit</button><button class="jtx jts" type="button">Sound on</button><div class="jtg"><canvas width="1000" height="500"></canvas>'
    +'<div class="jto" id="jtStart"><h3>Seafront Jet</h3><div class="jtb" id="jtSb"></div><p class="hint">Press an arrow key</p></div>'
    +'<div class="jto" id="jtEnd" hidden><h3>Crash landed</h3><div class="jtbig" id="jtEs"></div><p id="jtEb"></p><div class="jtb" id="jtBoard"></div><p class="hint">Press an arrow key</p></div></div>';
  document.body.appendChild(root);
  cv=root.querySelector("canvas");ctx=cv.getContext("2d");
  const btns=root.querySelectorAll(".jtx"),snd=btns[1];
  const lab=()=>{snd.textContent=AU.on?"Sound on":"Sound off"};lab();
  btns[0].addEventListener("click",closeGame);
  snd.addEventListener("click",()=>{AU.init();AU.toggle();lab()});
  S.mode="menu";S.t=0;S.dist=0;S.coins=0;S.lives=3;S.hz=[];S.cn=[];S.pt=[];S.dc=[];S.warn=[];
  for(const k in keys)keys[k]=false;
  window.addEventListener("keydown",onKey,true);window.addEventListener("keyup",onUp,true);window.addEventListener("blur",onBlur);
  AU.init();board($("#jtSb"));
  last=performance.now();raf=requestAnimationFrame(loop)}
function closeGame(){
  if(closed)return;closed=true;cancelAnimationFrame(raf);
  window.removeEventListener("keydown",onKey,true);window.removeEventListener("keyup",onUp,true);window.removeEventListener("blur",onBlur);
  AU.stop();AU.close();if(root){root.remove();root=null}cv=ctx=null;window.__pdOpen=false}
window.PortalJet={open};

